INSERT INTO risk_appetite_statements(entity_name,category,appetite_level,statement,escalation_trigger,approval_route) SELECT 'OSANVAULT AFRICA LTD','Legal & Regulatory','Low','The institution should maintain a low tolerance for breaches of mandatory law, regulatory obligations or binding court orders.','Suspected material breach, enforcement action or unresolved regulatory obligation.','Board / designated compliance function.' WHERE NOT EXISTS (SELECT 1 FROM risk_appetite_statements WHERE category='Legal & Regulatory');
INSERT INTO risk_appetite_statements(entity_name,category,appetite_level,statement,escalation_trigger,approval_route) SELECT 'OSANVAULT AFRICA LTD','Integrity & Ethics','Very Low','The institution should maintain zero tolerance for bribery, deliberate fraud, retaliation against protected reporting and falsification of institutional records.','Credible allegation or control failure indicating potential misconduct.','Ethics function + Board oversight.' WHERE NOT EXISTS (SELECT 1 FROM risk_appetite_statements WHERE category='Integrity & Ethics');
INSERT INTO risk_appetite_statements(entity_name,category,appetite_level,statement,escalation_trigger,approval_route) SELECT 'OSANVAULT AFRICA LTD','Indigenous & Community Rights','Low','The institution should maintain a low tolerance for avoidable adverse impacts on lawful indigenous, customary, ancestral or community interests.','Potential rights impact, inadequate consultation/consent where legally required, or material heritage concern.','Legal/compliance + stewardship governance + Board where material.' WHERE NOT EXISTS (SELECT 1 FROM risk_appetite_statements WHERE category='Indigenous & Community Rights');
INSERT INTO ethics_policies(entity_name,policy_code,policy_name,requirement,scope,escalation_route,training_requirement) SELECT 'OSANVAULT AFRICA LTD','ETH-01','Code of Institutional Ethics','Personnel and controlled representatives must act lawfully, honestly, independently and in the institution’s legitimate interests.','Directors, officers, employees, contractors and designated representatives.','Ethics & Board oversight.','Annual and onboarding.' WHERE NOT EXISTS (SELECT 1 FROM ethics_policies WHERE policy_code='ETH-01');
INSERT INTO ethics_policies(entity_name,policy_code,policy_name,requirement,scope,escalation_route,training_requirement) SELECT 'OSANVAULT AFRICA LTD','ETH-02','Anti-Bribery & Improper Influence','No offering, solicitation, authorization or concealment of improper payments or influence.','Institutional activities and third parties acting for the institution.','Ethics/Legal + Board where material.','Annual and role-based.' WHERE NOT EXISTS (SELECT 1 FROM ethics_policies WHERE policy_code='ETH-02');
INSERT INTO ethics_policies(entity_name,policy_code,policy_name,requirement,scope,escalation_route,training_requirement) SELECT 'OSANVAULT AFRICA LTD','ETH-03','Conflicts & Related Parties','Actual, potential and perceived conflicts should be disclosed, assessed, mitigated and documented before affected decisions.','Directors, officers, employees and relevant counterparties.','Governance/Legal + recusal and approval route.','Annual and event-driven.' WHERE NOT EXISTS (SELECT 1 FROM ethics_policies WHERE policy_code='ETH-03');
INSERT INTO ethics_policies(entity_name,policy_code,policy_name,requirement,scope,escalation_route,training_requirement) SELECT 'OSANVAULT AFRICA LTD','ETH-04','Protected Reporting & Non-Retaliation','Good-faith reporting should be confidentially handled with safeguards against retaliation, subject to law and due process.','Personnel, contractors and other permitted reporters.','Independent ethics function / Board committee.','Annual.' WHERE NOT EXISTS (SELECT 1 FROM ethics_policies WHERE policy_code='ETH-04');
INSERT INTO ethics_policies(entity_name,policy_code,policy_name,requirement,scope,escalation_route,training_requirement) SELECT 'OSANVAULT AFRICA LTD','ETH-05','Environmental & Social Safeguards','Material projects should identify environmental, social, heritage, community and rights impacts before execution.','Projects, assets and transactions with material impact potential.','Risk/Legal/Stewardship + Board where material.','Role-based.' WHERE NOT EXISTS (SELECT 1 FROM ethics_policies WHERE policy_code='ETH-05');
INSERT INTO risk_controls(entity_name,control_code,control_name,risk_category,control_type,description,owner_role,frequency,evidence_type,testing_method) SELECT 'OSANVAULT AFRICA LTD','CTRL-01','Regulatory Obligation Register','Legal & Regulatory','Preventive','Maintain a jurisdiction-specific register of applicable obligations, owners, evidence and review dates.','Governance/Legal','Monthly','Register and review log','Sample-based compliance testing.' WHERE NOT EXISTS (SELECT 1 FROM risk_controls WHERE control_code='CTRL-01');
INSERT INTO risk_controls(entity_name,control_code,control_name,risk_category,control_type,description,owner_role,frequency,evidence_type,testing_method) SELECT 'OSANVAULT AFRICA LTD','CTRL-02','Conflict Disclosure Gate','Integrity & Ethics','Preventive','Require conflict declaration and recusal assessment before affected governance decisions.','Governance Officer','Per decision','Declaration and minutes','Exception testing.' WHERE NOT EXISTS (SELECT 1 FROM risk_controls WHERE control_code='CTRL-02');
INSERT INTO risk_controls(entity_name,control_code,control_name,risk_category,control_type,description,owner_role,frequency,evidence_type,testing_method) SELECT 'OSANVAULT AFRICA LTD','CTRL-03','Protected Rights Impact Review','Indigenous & Community Rights','Preventive','Flag transactions and projects that may affect documented indigenous, customary, ancestral, cultural or community interests.','Stewardship/Legal','Per project or transaction','Impact assessment and evidence','Independent review where material.' WHERE NOT EXISTS (SELECT 1 FROM risk_controls WHERE control_code='CTRL-03');
INSERT INTO risk_controls(entity_name,control_code,control_name,risk_category,control_type,description,owner_role,frequency,evidence_type,testing_method) SELECT 'OSANVAULT AFRICA LTD','CTRL-04','Protected Reporting Safeguard','Integrity & Ethics','Detective','Maintain restricted handling, non-retaliation assessment, independent escalation and case closure evidence for protected reports.','Ethics & Assurance','Per report','Case log and closure evidence','Case file review.' WHERE NOT EXISTS (SELECT 1 FROM risk_controls WHERE control_code='CTRL-04');