CREATE TABLE IF NOT EXISTS institutional_risks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, risk_code text NOT NULL, risk_title text NOT NULL, risk_category text NOT NULL, description text NOT NULL, inherent_rating text NOT NULL DEFAULT 'Unassessed', likelihood text, impact text, risk_owner text, treatment text, residual_rating text DEFAULT 'Unassessed', review_frequency text DEFAULT 'Quarterly', status text NOT NULL DEFAULT 'Open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_appetite_statements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, category text NOT NULL, appetite_level text NOT NULL, statement text NOT NULL, quantitative_boundary text, escalation_trigger text, approval_route text, status text NOT NULL DEFAULT 'Proposed', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance_obligations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, obligation_code text NOT NULL, obligation_title text NOT NULL, jurisdiction text NOT NULL, regulator text, obligation_type text NOT NULL, description text NOT NULL, owner_role text, evidence_required text, review_frequency text, status text NOT NULL DEFAULT 'To Be Assessed', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS licences_and_registrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, licence_code text NOT NULL, licence_name text NOT NULL, jurisdiction text NOT NULL, regulator text, licence_number text, issue_date date, expiry_date date, status text NOT NULL DEFAULT 'Not Recorded', evidence_reference text, renewal_owner text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conflicts_and_related_parties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, case_code text NOT NULL, case_type text NOT NULL, subject_reference text, related_party text, relationship_description text, declared_by text, disclosure_date date, mitigation text, approval_route text, status text NOT NULL DEFAULT 'Open', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS protected_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, report_code text NOT NULL, report_type text NOT NULL, subject text NOT NULL, received_date date NOT NULL DEFAULT current_date, confidentiality_level text NOT NULL DEFAULT 'Restricted', assigned_function text, retaliation_risk text, status text NOT NULL DEFAULT 'Received', outcome text, closed_date date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS investigations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, investigation_code text NOT NULL, trigger_type text NOT NULL, subject_reference text, allegation_summary text NOT NULL, investigator_role text, independence_check text, opened_date date NOT NULL DEFAULT current_date, closed_date date, findings text, remediation_required text, status text NOT NULL DEFAULT 'Open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ethics_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, policy_code text NOT NULL, policy_name text NOT NULL, requirement text NOT NULL, scope text NOT NULL, escalation_route text, training_requirement text, review_frequency text DEFAULT 'Annual', status text NOT NULL DEFAULT 'Proposed', legal_review_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, control_code text NOT NULL, control_name text NOT NULL, risk_category text NOT NULL, control_type text NOT NULL, description text NOT NULL, owner_role text, frequency text, evidence_type text, testing_method text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS remediation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, action_code text NOT NULL, source_type text NOT NULL, source_reference text, action_description text NOT NULL, owner_role text, due_date date, priority text DEFAULT 'Medium', status text NOT NULL DEFAULT 'Open', closure_evidence text, created_at timestamptz NOT NULL DEFAULT now());
